<?php
require_once __DIR__ . '/../lib/bootstrap.php'; require_role('teacher','admin');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$t=post_string('title',150);if($t){$s=db()->prepare('INSERT INTO subjects(title,code,description,created_by) VALUES(?,?,?,?)');$s->execute([$t,post_string('code',50),post_string('description'),current_user()['id']]);flash('success','درس ایجاد شد.');}else flash('error','عنوان درس الزامی است.');redirect('teacher/subjects.php');}
$mine=current_user()['role']==='admin'?'1=1':'s.created_by='.((int)current_user()['id']);$subjects=db()->query("SELECT s.*,u.full_name creator FROM subjects s JOIN users u ON u.id=s.created_by WHERE $mine ORDER BY s.id DESC")->fetchAll();$classes=db()->query('SELECT id,title FROM classes ORDER BY title')->fetchAll();$title='مدیریت درس‌ها';require __DIR__.'/../partials/header.php';?><h1>درس‌ها</h1><div class="card"><form method="post" class="grid grid-2"><?=csrf_field()?><div class="form-group"><label>عنوان درس</label><input name="title" required></div><div class="form-group"><label>کد درس</label><input name="code"></div><div class="form-group"><label>توضیحات</label><textarea name="description"></textarea></div><div><button class="btn btn-primary">افزودن درس</button></div></form></div><div class="card table-wrap"><table class="table"><thead><tr><th>عنوان</th><th>کد</th><th>ایجادکننده</th><th>عملیات</th></tr></thead><tbody><?php foreach($subjects as $s):?><tr><td><?=e($s['title'])?></td><td><?=e($s['code'])?></td><td><?=e($s['creator'])?></td><td><a class="btn btn-sm btn-primary" href="<?=e(url('teacher/exams.php?subject_id='.$s['id']))?>">ساخت آزمون</a></td></tr><?php endforeach;?></tbody></table></div><?php require __DIR__.'/../partials/footer.php'; ?>
